builder.Services.AddOpenTelemetry()
    .ConfigureResource(r => r.AddService("orders-api"))
    .WithTracing(tracing => tracing
        .AddAspNetCoreInstrumentation()
        .AddHttpClientInstrumentation()
        .AddEntityFrameworkCoreInstrumentation()
        .AddSource("MyApp.Orders") // custom ActivitySource name
        .AddOtlpExporter(o =>
        {
            o.Endpoint = new Uri(builder.Configuration["Otlp:Endpoint"]!);
        }));

// Optional: also export to Azure Monitor
// .UseAzureMonitor()

public class PaymentService
{
    private static readonly ActivitySource Source = new("MyApp.Orders");

    public async Task ChargeAsync(Guid orderId, decimal amount)
    {
        using var activity = Source.StartActivity("ChargePayment", ActivityKind.Internal);
        activity?.SetTag("order.id", orderId.ToString());
        activity?.SetTag("payment.amount", amount);

        try
        {
            await _gateway.ChargeAsync(amount);
            activity?.SetStatus(ActivityStatusCode.Ok);
        }
        catch (Exception ex)
        {
            activity?.SetStatus(ActivityStatusCode.Error, ex.Message);
            activity?.RecordException(ex);
            throw;
        }
    }
}

